using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakIndependentTailInterior;
internal sealed class ModelDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Two exact source rows", H("Affine masks and physical packet heights"),
        Blocks(Paragraph(Text("Write x=tzw and y=2qx. The rational model uses the four original chain heads and their exact enlarged-source heads. Its four mask rows are [u,z/2-1,W0,D0], [3w/8-u-1,0,0,x/8], [w/8,0,4q-1-W0,x/2-2-D0-x/8], and [0,0,y/2-4q,1]. The negative terminal order is U,X,W,V. Each peak accumulates the actual positive bank mass after the previous terminal; the starting height is zero for the original source and A for the enlarged source. The associated expressions are the following seam and the upper-strip cap minus the peak. They are affine in D0 and W0, so interpolating these two mask coordinates interpolates every expression."))), []));
}
